"use strict";exports.id=9773,exports.ids=[9773],exports.modules={9773:e=>{e.exports=JSON.parse('{"page_label":"Com invertir","page_title":"Estrat\xe8gies d\'inversi\xf3","page_intro":"Aquests s\xf3n els enfocaments m\xe9s habituals per comprar bitcoin. Tria el que millor s\'adapti a la teva personalitat i situaci\xf3.","guides_label":"Abans de comen\xe7ar","guides_title":"Punts clau a l\'hora d\'invertir","guides_intro":"Uns principis senzills que t\'estalviaran diners, ansietat i penediments. Llegeix-los abans de res.","guide_sleep_title":"Dormir a la nit","guide_sleep_text":"Si una inversi\xf3 et treu la son o et genera ansietat, no \xe9s una bona inversi\xf3. Protegir la teva tranquil\xb7litat forma part de la estrat\xe8gia.","guide_lose_title":"Inverteix nom\xe9s el que pots perdre","guide_lose_text":"Dimensiona la teva inversi\xf3 en base a les possibles p\xe8rdues, no en els guanys. Mai inverteixis diners destinats al lloguer, al menjar o a les factures.","guide_vote_title":"Invertir \xe9s votar","guide_vote_text":"On poses els teus diners \xe9s on poses la teva energia. Inverteix en all\xf2 en qu\xe8 creus. Els diners invertits en guerra alimenten la guerra. Els diners invertits en energia renovable alimenten l\'energia renovable.","guide_time_title":"Sigues pacient","guide_time_text":"Ning\xfa sap els m\xe0xims ni els m\xednims. Inverteix peri\xf2dicament, espera amb paci\xe8ncia i deixa que els teus diners treballin per tu.","strat_a_title":"DCA \xb7 Dollar Cost Averaging","strat_a_subtitle":"El millor amic del principiant","strat_a_badge":"Recomanat","strat_a_body_1":"Tria un import mensual fix i assequible (p. ex. 50 €). Compra bitcoin cada mes, independentment del preu. Alguns mesos comprar\xe0s m\xe9s bitcoins, d\'altres menys.","strat_a_body_2":"No cal con\xe8ixer el mercat. Nom\xe9s paci\xe8ncia i disciplina. Mant\xe9n durant almenys un cicle complet (~4 anys).","strat_a_tip":"\xc9s avorrit. Posa un recordatori, compra i segueix endavant. No miris el preu.","strat_b_title":"DCA Ponderat \xb7 DCA v2","strat_b_subtitle":"La mateixa idea, per\xf2 amb una execuci\xf3 m\xe9s intel\xb7ligent","strat_b_badge":"Intermedi","strat_b_body_1":"Igual que el DCA per\xf2 adapta l\'import mensual segons les condicions del mercat. Estableix un rang (p. ex. 0 €–100 €/mes). Quan bitcoin estigui barat [per senyals com RSI <30, por en el mercat o poques adreces en positiu; inverteix m\xe9s. Quan el bitcoin faci r\xe8cords, inverteix menys.","strat_b_body_2":"En caigudes fortes, augmenta temporalment la teva inversi\xf3 utilitzant diners addicionals, per\xf2 mai els d\'emerg\xe8ncia. No apuntis al m\xednim absolut.","strat_b_metrics_link":"M\xe8triques","strat_b_tip":"No est\xe0s intentant encertar el mercat, simplement intentes optimitzar la teva inversi\xf3.","strat_c_title":"Lump-Sum \xb7 All-in quan est\xe0 baix","strat_c_subtitle":"Alt risc, alta recompensa — no apte per a principiants","strat_c_badge":"Avan\xe7at","strat_c_body_1":"Espera una caiguda important i aleshores inverteix una gran quantitat d\'un cop. Fant\xe0stic en teoria, molt dif\xedcil emocionalment en la pr\xe0ctica. Requereix con\xe8ixer almenys un cicle complet de Bitcoin (~4 anys).","strat_c_body_2":"Sense experi\xe8ncia, \xe9s f\xe0cil comprar massa aviat, vendre en p\xe0nic o perdre la oportunitat. Aix\xf2 s\'acosta m\xe9s al trading que a la inversi\xf3 — busca cursos especialitzats fora d\'aquesta p\xe0gina si vols aprendre\'n.","strat_c_tip":"La majoria de la gent \xe9s millor amb DCA. El lump-sum sembla genial a posteriori, per\xf2 \xe9s brutal en temps real.","strat_d_title":"Or \xb7 El refugi de sempre","strat_d_subtitle":"Per als qui prefereixen estabilitat a volatilitat","strat_d_badge":"Alternativa","strat_d_body_1":"Si el Bitcoin et sembla massa vol\xe0til, no passa res, per\xf2 no fer res tampoc \xe9s segur. La inflaci\xf3 es menja silenciosament els teus estalvis cada any. L\'or ha estat una reserva de valor fiable durant milers d\'anys.","strat_d_body_2":"Compra or f\xedsic com a mesura de protecci\xf3. Per saber com invertir en or, busca plataformes especialitzades.","strat_d_tip":"Dit aix\xf2, ves comprant almenys una mica de bitcoin. Ja saps per qu\xe8 \uD83D\uDE09","metrics_link_text":"M\xe8triques"}')}};